describe("naming helpers", () => {
  it("converts cases and handles digits/symbols", () => {
    expect(pascal("first-name")).toBe("FirstName");
    expect(pascal("$ref")).toBe("Ref");
    expect(pascal("2fa")).toBe("N2fa");
    expect(pascal("@@")).toBe("Field");
    expect(camel("First Name")).toBe("firstName");
    expect(snake("avatarURL")).toBe("avatar_url");
    expect(snake("#text")).toBe("text");
    expect(goPascal("user_id")).toBe("UserID");
    expect(goPascal("avatarUrl")).toBe("AvatarURL");
    expect(goPascal("identity")).toBe("Identity");
    expect(screaming("in-progress")).toBe("IN_PROGRESS");
  });

  it("singularizes English plurals", () => {
    expect(singular("orders")).toBe("order");
    expect(singular("categories")).toBe("category");
    expect(singular("addresses")).toBe("address");
    expect(singular("statuses")).toBe("status");
    expect(singular("lineItems")).toBe("lineItem");
    expect(singular("children")).toBe("child");
    expect(singular("Children")).toBe("Child");
    expect(singular("SalesPeople")).toBe("SalesPerson");
    expect(singular("data")).toBeNull();
    expect(singular("status")).toBeNull();
    expect(singular("address")).toBeNull();
  });
});

describe("9-target type codegen", () => {
  it("matches all 36 golden snapshots byte-for-byte", () => {
    for (const c of ORACLE_CASES) {
      for (const language of CODEGEN_LANGUAGES) {
        const res = generateFromJsonText(c.json, { language, rootName: c.stem });
        expect(res.code.trimEnd()).toBe(c.expected[language].trimEnd());
      }
    }
  });

  it("supports configurable root name, deduplication, and parent qualification", () => {
    const res1 = generateFromJsonText(`{"a": {"b": 1}}`, {
      language: "typescript",
      rootName: "api response",
    });
    expect(res1.code.startsWith("export interface ApiResponse {\n  a: A;\n}")).toBe(true);

    const dup = `{
      "home": {"street": "a", "city": "b"},
      "work": {"street": "c", "city": "d"},
      "customer": {"address": {"street": "e"}},
      "warehouse": {"address": {"lat": 1.5}}
    }`;
    const ts = generateFromJsonText(dup, { language: "typescript" }).code;
    const names = ts
      .split("\n")
      .filter((l) => l.startsWith("export interface "))
      .map((l) => l.slice("export interface ".length));
    expect(names).toEqual([
      "Root {",
      "Home {",
      "Customer {",
      "Warehouse {",
      "Address {",
      "WarehouseAddress {",
    ]);
    expect(ts).toContain("  work: Home;");
  });

  it("emits aliases for scalar and array roots and respects maxEnum = 0", () => {
    const arrTs = generateFromJsonText("[1, 2]", { language: "typescript" }).code;
    expect(arrTs).toBe("export type Root = number[];\n");

    const goEvents = generateFromJsonText(`[{"a": 1}]`, {
      language: "go",
      rootName: "events",
    }).code;
    expect(goEvents).toContain(
      'type Events []Event\n\ntype Event struct {\n\tA int64 `json:"a"`\n}',
    );

    const rsStr = generateFromJsonText(`"x"`, { language: "rust" }).code;
    expect(rsStr).toContain("pub type Root = String;");

    const enumSrc = `[{"s": "a"}, {"s": "b"}, {"s": "a"}]`;
    const enumOn = generateFromJsonText(enumSrc, { language: "typescript" }).code;
    expect(enumOn).toContain('export type S = "a" | "b";');

    const enumOff = generateFromJsonText(enumSrc, { language: "typescript", maxEnum: 0 }).code;
    expect(enumOff).toContain("  s: string;");
  });
});
